// Cross-language pins: generated by the C++ oracle (same source, same
// XXH3). Any hash or layout divergence fails here first.
func TestCrossLanguageVectors(t *testing.T) {
	r, err := New(150, 0)
	if err != nil {
		t.Fatal(err)
	}
	r.AddNode("node1")
	r.AddNode("node2")
	r.AddNode("node3")
	want := map[string][3]string{
		"":                          {"node2", "node1", "node3"},
		"k":                         {"node1", "node2", "node3"},
		"key-0":                     {"node2", "node1", "node3"},
		"hello":                     {"node2", "node1", "node3"},
		"some-long-key-value-12345": {"node3", "node1", "node2"},
		"counter-7":                 {"node1", "node3", "node2"},
	}
	for key, w := range want {
		got, err := r.GetNodes(key, 3)
		if err != nil {
			t.Fatal(err)
		}
		if len(got) != 3 || got[0] != w[0] || got[1] != w[1] || got[2] != w[2] {
			t.Fatalf("key %q: got %v, want %v", key, got, w)
		}
	}

	r2, err := New(10, 0)
	if err != nil {
		t.Fatal(err)
	}
	r2.AddNode("alpha")
	r2.AddNode("beta")
	for _, key := range []string{"a", "b", "abc", "key999"} {
		if got := r2.GetNode(key); got != "alpha" {
			t.Fatalf("key %q: got %q, want alpha", key, got)
		}
	}
}

func mustRing(t *testing.T, vnodes int, factor float64) *Ring {
	t.Helper()
	r, err := New(vnodes, factor)
	if err != nil {
		t.Fatal(err)
	}
	return r
}

func TestSingleNode(t *testing.T) {
	r := mustRing(t, 10, 0)
	r.AddNode("node1")
	for i := range 100 {
		if got := r.GetNode(fmt.Sprintf("key%d", i)); got != "node1" {
			t.Fatalf("got %q", got)
		}
	}
}

func TestMultipleNodes(t *testing.T) {
	r := mustRing(t, 50, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	r.AddNode("node3")
	seen := map[string]struct{}{}
	for i := range 1000 {
		seen[r.GetNode(fmt.Sprintf("key%d", i))] = struct{}{}
	}
	if len(seen) != 3 {
		t.Fatalf("seen %v", seen)
	}
}

func TestAddNodeDistributes(t *testing.T) {
	r := mustRing(t, 100, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	counts := map[string]int{}
	for i := range 10000 {
		counts[r.GetNode(fmt.Sprintf("key%d", i))]++
	}
	for _, n := range []string{"node1", "node2"} {
		if counts[n] < 4000 || counts[n] > 6000 {
			t.Fatalf("counts = %v", counts)
		}
	}
}

func TestRemoveNode(t *testing.T) {
	r := mustRing(t, 50, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	r.RemoveNode("node1")
	for i := range 1000 {
		if got := r.GetNode(fmt.Sprintf("key%d", i)); got != "node2" {
			t.Fatalf("got %q", got)
		}
	}
}

func TestGetNodesReplicaCount(t *testing.T) {
	r := mustRing(t, 50, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	r.AddNode("node3")
	for i := range 100 {
		nodes, err := r.GetNodes(fmt.Sprintf("key%d", i), 2)
		if err != nil || len(nodes) != 2 || nodes[0] == nodes[1] {
			t.Fatalf("got %v, %v", nodes, err)
		}
	}
}

func TestGetNodesNotExceedingAlive(t *testing.T) {
	r := mustRing(t, 50, 0)
	r.AddNode("node1")
	for i := range 100 {
		nodes, err := r.GetNodes(fmt.Sprintf("key%d", i), 3)
		if err != nil || len(nodes) != 1 {
			t.Fatalf("got %v, %v", nodes, err)
		}
	}
}

func TestMinimalRemappingOnAdd(t *testing.T) {
	r := mustRing(t, 150, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	before := map[string]string{}
	for i := range 10000 {
		k := fmt.Sprintf("key%d", i)
		before[k] = r.GetNode(k)
	}
	r.AddNode("node3")
	moved := 0
	for k, old := range before {
		if r.GetNode(k) != old {
			moved++
		}
	}
	if moved >= 4500 {
		t.Fatalf("moved = %d", moved)
	}
}

func TestGetNodesAllDistinct(t *testing.T) {
	r := mustRing(t, 50, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	r.AddNode("node3")
	for i := range 200 {
		nodes, err := r.GetNodes(fmt.Sprintf("key%d", i), 3)
		if err != nil || len(nodes) != 3 || nodes[0] == nodes[1] || nodes[0] == nodes[2] || nodes[1] == nodes[2] {
			t.Fatalf("got %v, %v", nodes, err)
		}
	}
}

func TestGetNodesReplicaCountExceedsAlive(t *testing.T) {
	r := mustRing(t, 50, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	for i := range 200 {
		nodes, err := r.GetNodes(fmt.Sprintf("key%d", i), 8)
		if err != nil || len(nodes) > 2 {
			t.Fatalf("got %v, %v", nodes, err)
		}
	}
}

func TestAddNodeIdempotent(t *testing.T) {
	r := mustRing(t, 10, 0)
	r.AddNode("node1")
	r.AddNode("node1")
	r.AddNode("node2")
	for i := range 200 {
		nodes, err := r.GetNodes(fmt.Sprintf("key%d", i), 2)
		if err != nil || len(nodes) != 2 || nodes[0] == nodes[1] {
			t.Fatalf("got %v, %v", nodes, err)
		}
	}
	r.RemoveNode("node2")
	r.AddNode("node2")
	for i := range 200 {
		nodes, err := r.GetNodes(fmt.Sprintf("key%d", i), 2)
		if err != nil || len(nodes) != 2 {
			t.Fatalf("got %v, %v", nodes, err)
		}
	}
}

func TestEmptyRingLookupsAreSafe(t *testing.T) {
	r := mustRing(t, 150, 0)
	if got := r.GetNode("key"); got != "" {
		t.Fatalf("got %q", got)
	}
	for _, n := range []int{0, -1, 33} {
		if _, err := r.GetNodes("key", n); !errors.Is(err, ErrInvalidReplicaCount) {
			t.Fatalf("n=%d: err = %v", n, err)
		}
	}
}

func TestInvalidConfigurationRejected(t *testing.T) {
	if _, err := New(0, 0); err == nil {
		t.Fatal("vnodes 0 accepted")
	}
	if _, err := New(-1, 0); err == nil {
		t.Fatal("vnodes -1 accepted")
	}
	if _, err := New(1, -1); err == nil {
		t.Fatal("negative factor accepted")
	}
	if _, err := New(1, math.Inf(1)); err == nil {
		t.Fatal("+Inf factor accepted")
	}
}

func TestSetNodesMatchesIncremental(t *testing.T) {
	inc := mustRing(t, 32, 0)
	inc.AddNode("node-a")
	inc.AddNode("node-b")
	inc.AddNode("node-c")
	bulk := mustRing(t, 32, 0)
	if err := bulk.SetNodes([]string{"node-a", "node-b", "node-c", "node-b"}); err != nil {
		t.Fatal(err)
	}
	for i := range 1000 {
		k := fmt.Sprintf("key-%d", i)
		if bulk.GetNode(k) != inc.GetNode(k) {
			t.Fatalf("key %q diverges", k)
		}
		a, _ := bulk.GetNodes(k, 3)
		b, _ := inc.GetNodes(k, 3)
		if len(a) != len(b) || a[0] != b[0] || a[1] != b[1] || a[2] != b[2] {
			t.Fatalf("key %q: %v vs %v", k, a, b)
		}
	}
}

func TestSetNodesKeepsSurvivorLoads(t *testing.T) {
	r := mustRing(t, 16, 0)
	if err := r.SetNodes([]string{"node-a", "node-b"}); err != nil {
		t.Fatal(err)
	}
	r.IncrementLoad("node-a")
	r.IncrementLoad("node-b")
	if err := r.SetNodes([]string{"node-b", "node-c"}); err != nil {
		t.Fatal(err)
	}
	if r.CurrentLoad("node-b") != 1 || r.CurrentLoad("node-a") != 0 || r.CurrentLoad("node-c") != 0 {
		t.Fatal("survivor loads wrong")
	}
	if err := r.SetNodes([]string{"node-a", "node-b"}); err != nil {
		t.Fatal(err)
	}
	if r.CurrentLoad("node-a") != 0 || r.CurrentLoad("node-b") != 1 {
		t.Fatal("rejoined node must reset, survivor must keep")
	}
}

func TestSetNodesEmptyAndDuplicatesAreNoops(t *testing.T) {
	r := mustRing(t, 8, 0)
	if err := r.SetNodes([]string{"node-a", "node-b"}); err != nil {
		t.Fatal(err)
	}
	before := r.GetNode("key")
	if err := r.SetNodes([]string{"node-a", "node-b", "node-a"}); err != nil {
		t.Fatal(err)
	}
	if got := r.GetNode("key"); got != before {
		t.Fatal("duplicate update must be a no-op")
	}
	if err := r.SetNodes(nil); err != nil {
		t.Fatal(err)
	}
	if got := r.GetNode("key"); got != "" {
		t.Fatal("empty set must clear the ring")
	}
	if nodes, _ := r.GetNodes("key", 1); len(nodes) != 0 {
		t.Fatal("empty ring must yield no nodes")
	}
}

func TestBoundedSingleNode(t *testing.T) {
	r := mustRing(t, 10, 1.0)
	r.AddNode("node1")
	for i := range 100 {
		if got := r.GetNodeBounded(fmt.Sprintf("key%d", i)); got != "node1" {
			t.Fatalf("got %q", got)
		}
	}
}

func TestBoundedBalancedDistributes(t *testing.T) {
	r := mustRing(t, 50, 1.0)
	r.AddNode("node1")
	r.AddNode("node2")
	counts := map[string]int{}
	for i := range 10000 {
		counts[r.GetNodeBounded(fmt.Sprintf("key%d", i))]++
	}
	for _, n := range []string{"node1", "node2"} {
		if counts[n] < 3500 || counts[n] > 6500 {
			t.Fatalf("counts = %v", counts)
		}
	}
}

func TestBoundedOverloadedSpills(t *testing.T) {
	r := mustRing(t, 50, 1.0)
	r.AddNode("node1")
	r.AddNode("node2")
	spill := ""
	for i := range 10000 {
		if k := fmt.Sprintf("spill%d", i); r.GetNode(k) == "node1" {
			spill = k
			break
		}
	}
	if spill == "" {
		t.Fatal("no key maps to node1")
	}
	if got := r.GetNodeBounded(spill); got != "node1" {
		t.Fatalf("no-load bounded = %q", got)
	}
	r.IncrementLoad("node1")
	r.IncrementLoad("node1")
	if got := r.GetNodeBounded(spill); got != "node2" {
		t.Fatalf("overloaded bounded = %q", got)
	}
	r.DecrementLoad("node1")
	r.DecrementLoad("node1")
}

func TestBoundedAllOverloadedWraps(t *testing.T) {
	r := mustRing(t, 50, 1.0)
	r.AddNode("node1")
	r.AddNode("node2")
	r.IncrementLoad("node1")
	r.IncrementLoad("node2")
	got := r.GetNodeBounded("any-key")
	if got != "node1" && got != "node2" {
		t.Fatalf("got %q", got)
	}
	r.DecrementLoad("node1")
	r.DecrementLoad("node2")
}

func TestLoadTracking(t *testing.T) {
	r := mustRing(t, 10, 1.0)
	r.AddNode("node1")
	r.AddNode("node2")
	r.IncrementLoad("node1")
	r.IncrementLoad("node1")
	r.IncrementLoad("ghost")
	if r.CurrentLoad("node1") != 2 || r.CurrentLoad("node2") != 0 || r.CurrentLoad("ghost") != 0 {
		t.Fatal("loads wrong")
	}
	if r.TotalLoad() != 2 {
		t.Fatalf("total = %d", r.TotalLoad())
	}
	r.DecrementLoad("node1")
	if r.CurrentLoad("node1") != 1 {
		t.Fatal("decrement wrong")
	}
}

func TestLoadPersistsAcrossMembershipChange(t *testing.T) {
	r := mustRing(t, 16, 1.0)
	r.AddNode("node-a")
	r.AddNode("node-b")
	r.IncrementLoad("node-a")
	r.AddNode("node-c")
	if r.CurrentLoad("node-a") != 1 {
		t.Fatal("add must preserve loads")
	}
	r.RemoveNode("node-c")
	if r.CurrentLoad("node-a") != 1 {
		t.Fatal("remove must preserve loads")
	}
}

func TestConcurrentReads(t *testing.T) {
	r := mustRing(t, 100, 0)
	r.AddNode("node1")
	r.AddNode("node2")
	r.AddNode("node3")
	var wg sync.WaitGroup
	for range 4 {
		wg.Go(func() {
			for i := range 1000 {
				_ = r.GetNode(fmt.Sprintf("key%d", i))
				_, _ = r.GetNodes(fmt.Sprintf("key%d", i), 2)
			}
		})
	}
	wg.Wait()
}
